import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import './../assets/css/login.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faEye, faEyeSlash } from '@fortawesome/free-solid-svg-icons';

const Login = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const { email, password } = formData;
  const navigate = useNavigate();

  // Handle input change
  const onChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  // Handle form submit
  const onSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', formData);
      localStorage.setItem('token', res.data.token);
      localStorage.setItem('role', res.data.role);

      if (res.data.role === 'admin') {
        navigate('/admin-dashboard');
      } else if (res.data.role === 'teacher') {
        navigate('/teacher-dashboard');
      }
    } catch (err) {
      if (err.response) {
        alert(err.response.data.msg);
      } else {
        alert('Network Error. Please try again.');
      }
    }
  };

  // Toggle password visibility
  const togglePasswordVisibility = () => {
    setShowPassword((prev) => !prev);
  };

  return (
    <div className="login-page">
      <div className="login-container">
        {/* Left Column: Branding */}
        <div className="branding-column">
          <div className="branding-content">
            <h1 className="welcome-message">Welcome to</h1>
            <h2 className="school-name">Eklavya Children Academy</h2>
            <img
              src={require('./../assets/images/login-illustration.png')}
              alt="Illustration"
              className="illustration-image"
            />
            <p className="quote">
              "Education is the most powerful weapon which you can use to change the world."
            </p>
            <p className="quote-author">- Nelson Mandela</p>
          </div>
        </div>

        {/* Right Column: Login Form */}
        <div className="form-column">
          <div className="login-form-container">
            {/* Title */}
            <div className="school-logo">
              <p className="school-text">School</p>
              <p className="school-subtext">
                Management <span>System</span>
              </p>
            </div>

            <p className="login-title">Log in</p>

            <form onSubmit={onSubmit}>
              {/* Office Select */}
              <div className="select-group">
                <select className="office-select" defaultValue="Head Office">
                  <option value="Head Office">Head Office</option>
                </select>
              </div>

              {/* User ID */}
              <div className="input-group">
                <input
                  type="text"
                  name="email"
                  value={email}
                  onChange={onChange}
                  placeholder="User ID"
                  required
                />
              </div>

              {/* Password */}
              <div className="input-group password-group">
                <input
                  type={showPassword ? 'text' : 'password'}
                  name="password"
                  value={password}
                  onChange={onChange}
                  placeholder="Password"
                  required
                />
                <FontAwesomeIcon
                  icon={showPassword ? faEyeSlash : faEye}
                  className="password-toggle"
                  onClick={togglePasswordVisibility}
                  title={showPassword ? 'Hide Password' : 'Show Password'}
                />
              </div>

              {/* Captcha */}
              <div className="recaptcha-group">
                <input
                  type="text"
                  placeholder="Enter CAPTCHA"
                  className="captcha-input"
                  required
                />
                <span className="captcha-text">9CCEH</span>
              </div>

              {/* Submit */}
              <button type="submit" className="login-btn">
                Login
              </button>

              {/* Forgot Password */}
              <a href="/forgot-password" className="forgot-password">
                Forgot your password?
              </a>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
